import {pageHeader,emptyState,dataTable,recordCard,listToolbar,navigation,appShell,detailLayout} from './components.js';
const isPreview=true;
const $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let S=null,view='today',filters={q:'',building:'',floor:'',status:'',area:''},page=0,selected=new Set(),selectedDate='',issueState='Open',blockedHistory=false,sortKey='route',pending=null,opened=null;
let routeStorage;try{routeStorage=window.localStorage}catch{}
const routeStore=createRouteStore(routeStorage);let routeSession=null,routeQuery=null,todayOwner='all',todayBlocked=false;let activeRoute='',uf={q:'',owner:'',status:''};
const dialog=$('#detail'),body=$('#dialog-body');
let labelMode=false,initialForm='',saving=false,uncertain=false,listContext=null,detailAction='',receipt=null,receiptKey='',versionOverride=null,refreshFailed=false;
const initialDestination=readDestination(typeof location==='undefined'?{}:location);view=initialDestination.view;
let deepLink=initialDestination.record,modalHistory=false,historyClosing=false,deferredRecord=null,deferredTimer=null,modalURL='';
function pushModalHistory(){if(!historyClosing&&window.history?.pushState){window.history.pushState({...window.history.state,beakerDetail:true},'');modalHistory=true}}
function releaseModalHistory(){if(modalHistory&&window.history?.back){modalHistory=false;historyClosing=true;window.history.back()}}
function applyDestination(){const next=readDestination(window.location),restoreURL=()=>{if(modalURL)window.history?.replaceState(window.history.state,'',modalURL)};const go=()=>{if(dialog.open){modalHistory=false;dialog.close();opened=null;detailAction='';restoreContext()}view=next.view;if(S){render();if(next.record)open(next.record.kind,next.record.id)}else deepLink=next.record};if(guard(go,restoreURL))go();else if(saving)restoreURL()}

window.addEventListener('popstate',()=>{if(historyClosing){historyClosing=false;if(dialog.open&&!modalHistory)pushModalHistory();return}if(dialog.open){if(window.location?.href!==modalURL){applyDestination();return}modalHistory=false;pushModalHistory();backDetail()}else if(S)applyDestination()});
window.addEventListener('hashchange',()=>{if(S)applyDestination()});
window.addEventListener('beforeunload',event=>{if(dialog.open&&(dirty()||uncertain||saving)){event.preventDefault();event.returnValue=''}});
function draftSignature(){const f=$('#edit-form');return f?JSON.stringify([...f.querySelectorAll('input,select,textarea')].map((input,index)=>[input.name||input.id||index,input.type==='checkbox'?input.checked:input.type==='file'?[...input.files].map(file=>file.name):input.value])):''}
function dirty(){return draftSignature()!==initialForm}
function guard(next,onKeep=null){
 if(saving){notice('Saving… Wait for the result before leaving.');return false}
 if(!dialog.open||!dirty()&&!uncertain)return true;
 if($('#dirty-guard'))return false;
 const active=document.activeElement,box=document.createElement('section');box.id='dirty-guard';box.className='warning';box.setAttribute('role','alert');
 box.innerHTML='<strong>Keep your changes?</strong><p>'+ (uncertain?'Save not confirmed. Discarding leaves its outcome unknown; verify the record before making another change.':'You have unsaved changes.')+'</p><button type="button" id="keep-editing">Keep editing</button> <button type="button" id="discard-draft">Discard</button>';
 $('.dialog-content').prepend(box);$('#keep-editing').onclick=()=>{box.remove();onKeep?.();active?.focus()};$('#discard-draft').onclick=()=>{box.remove();initialForm=draftSignature();uncertain=false;pending=null;next()};$('#keep-editing').focus();return false;
}
function closeDetail(){if(!guard(closeDetail))return;dialog.close();releaseModalHistory();opened=null;detailAction='';restoreContext()}
function restoreContext(){if(!listContext)return;const context=listContext;listContext=null;window.scrollTo?.(context.x,context.y);for(const [key,value] of context.focus){if(!value)continue;const target=[...document.querySelectorAll('['+key+']')].find(el=>el.getAttribute(key)===value&&el.getClientRects().length);if(target){target.focus({preventScroll:true});break}}}

function backDetail(){if(!guard(backDetail))return;if(detailAction&&opened){detailAction='';open(opened.kind,opened.id)}else closeDetail()}

function notice(t){$('#notice').textContent=t;$('#notice').style.display='block';setTimeout(()=>$('#notice').style.display='none',4500)}
async function api(path,data){return demoAPI(path,data)}
async function load(){S=await api('state');refreshFailed=false;if(routeSession)routeSession.refresh(routeMatches(),S.printers);if(!selectedDate)selectedDate=S.today;render();if(deepLink){const link=deepLink;deepLink=null;open(link.kind,link.id)}}
function badge(v){return `<span class="badge ${esc(String(v||'').toLowerCase().replaceAll(' ','-'))}">${esc(v||'Unknown')}</span>`}
function dateDisplay(v){if(!v)return 'Unknown';if(/^\d{4}-\d{2}-\d{2}$/.test(v))return v;try{return new Intl.DateTimeFormat('en-US',{timeZone:'America/Chicago',dateStyle:'medium',timeStyle:'short'}).format(new Date(v))}catch{return v}}
function canEdit(){return S.identity.role!=='viewer'}
function head(title,actions=''){return pageHeader(title,actions)}
function opts(items,value,first='All'){return `<option value="">${esc(first)}</option>`+items.map(v=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(v||'(Blank)')}</option>`).join('')}
function empty(title,sub=''){return emptyState(title,sub)}
function table(headers,rows,cards){return dataTable(headers,rows,cards)}
function nav(){let links=[['printers','Printers',S.printers.length],['issues','Issues',S.issues.filter(i=>i.state==='Open').length],['today','Today',S.agenda.filter(a=>a.work_date===selectedDate).length],['blocked','Blocked',S.blockers.filter(b=>!b.closed_at).length],['units','Provisioning',S.units.length],['tickets','Tickets',S.tickets.length],['mappings','Mappings',''],['tools','Tools',''],['history','History',''],['settings','Settings','']];return navigation(links,view)}
function render(){let active=document.activeElement;let focusAttributes=['id','data-view','data-filter','data-unit-filter','data-ticket-filter','data-select','data-act','data-open','data-settings','data-audit','data-work-open','data-work-schedule','data-printer-quick','data-task-quick'];let focusIdentity=active&&focusAttributes.map(k=>[k,active.getAttribute(k)]).find(([,v])=>v);let content={printers:printers,issues:issues,today:tasks,blocked:blockers,units:units,tickets:tickets,mappings:mappings,tools:tools,history:history,settings:settings,more:more}[view]();$('#app').innerHTML=appShell({content,nav:nav(),view,identity:S.identity,preview:true});wire();if(focusIdentity&&!dialog.open){let [key,value]=focusIdentity;let matches=[...document.querySelectorAll('['+key+']')];let target=matches.find(e=>e.getAttribute(key)===value&&e.getClientRects().length);target?.focus({preventScroll:true})}}
function filteredPrinters(f=filters,order=sortKey){let q=f.q.trim().toUpperCase().replace(/^HN(?=\d{4}$)/,'');return S.printers.filter(p=>(!q||[p.serial,p.location,p.epr].some(v=>String(v||'').toUpperCase().includes(q)))&&['building','floor','status','area'].every(k=>!f[k]||String(p[k]||'')===f[k]||f[k]==='__blank'&&!p[k])).sort((a,b)=>order==='route'?(a.status==='Complete')-(b.status==='Complete')||a.area_order-b.area_order||String(a.building).localeCompare(String(b.building),undefined,{numeric:true})||String(a.floor).localeCompare(String(b.floor),undefined,{numeric:true})||a.location.localeCompare(b.location,undefined,{numeric:true})||a.serial.localeCompare(b.serial):String(a[order]||'').localeCompare(String(b[order]||''),undefined,{numeric:true}))}
function routeMatches(){return filteredPrinters(routeQuery.filters,routeQuery.sort)}
function routeControls(){return `<div class="saved-routes"><label>Saved route<select id="saved-route"><option value="">Choose a route</option>${routeStore.list().map(r=>`<option value="${esc(r.name)}" ${activeRoute===r.name?'selected':''}>${esc(r.name)}</option>`).join('')}</select></label><button data-act="save-route">Save current route</button><button class="tertiary" data-act="remove-route" ${activeRoute?'':'disabled'}>Remove saved route</button></div>`}
function filterFields(){return ['building','floor','status','area'].map(k=>`<label>${esc(k[0].toUpperCase()+k.slice(1))}<select aria-label="${k}" data-filter="${k}">${opts([...new Set(S.printers.map(p=>String(p[k]||'')).filter(Boolean))].sort(),filters[k],'All '+k)}<option value="__blank" ${filters[k]==='__blank'?'selected':''}>(Blank)</option></select></label>`).join('')}
function printers(){
 const list=filteredPrinters();page=Math.min(page,Math.max(0,Math.ceil(list.length/40)-1));const shown=list.slice(page*40,(page+1)*40),hidden=[...selected].filter(id=>!list.some(p=>p.id===id)).length;
 const chips=['building','floor','status','area'].filter(k=>filters[k]).map(k=>`<button class="filter-chip" data-clear-filter="${k}" aria-label="Remove ${k} filter">${esc(k)}: ${esc(filters[k]==='__blank'?'Blank':filters[k])} ×</button>`).join('');
 const selection=labelMode?`<div class="toolbar selection-toolbar"><button data-act="select-visible">Select matching results</button><button class="primary" data-act="review" ${selected.size?'':'disabled'}>Review labels · ${selected.size}</button><button data-act="clear-selection" ${selected.size?'':'disabled'}>Clear selection</button><button data-act="toggle-labels">Done selecting</button></div>`:'';
 const check=p=>`<label class="check compact"><input type="checkbox" aria-label="Select ${esc(p.serial)}" data-select="${p.id}" ${selected.has(p.id)?'checked':''}>Select for labels</label>`;
 if(routeSession)return routeWork();
 return head('Find',`<button data-act="refresh">Refresh</button>`)+`<section class="find-controls">${listToolbar(`<input class="search" id="search" spellcheck="false" aria-label="Find printer" placeholder="Location ID, serial or HN / EPR" autocomplete="off" autocapitalize="characters" value="${esc(filters.q)}">`)}<div class="toolbar"><button data-act="filters">Filters${chips?' · '+['building','floor','status','area'].filter(k=>filters[k]).length:''}</button><button data-act="routes">Routes</button><button data-act="toggle-labels" aria-pressed="${labelMode}">${labelMode?'Selecting labels':'Select labels'}${!labelMode&&selected.size?' · '+selected.size:''}</button><select id="sort" aria-label="Sort">${['route','location','serial','status'].map(v=>`<option ${sortKey===v?'selected':''}>${v}</option>`).join('')}</select></div>${chips?`<div class="active-filters">${chips}<button data-act="clear">Clear filters</button></div>`:''}</section>${selection}<div class="countline"><span>${list.length.toLocaleString()} printers${hidden?` · ${hidden} selected outside these filters`:''}</span>${labelMode?`<span>${selected.size} selected</span>`:''}</div>${refreshFailed?'<div class="warning">Current records could not refresh. Displayed lists may be out of date.</div>':''}`+(list.length?table([...(labelMode?['Select']:[]),'Location ID','Serial','Building / Floor','Area','Status','Mapping'],shown.map(p=>`<tr>${labelMode?`<td>${check(p)}</td>`:''}<td><button class="row-link identifier" data-open="printer:${p.id}">${esc(p.location||'No Location ID')}</button></td><td class="identifier">${esc(p.serial)}</td><td>${esc(p.building||'—')} / ${esc(p.floor||'—')}</td><td>${esc(p.area||'—')}</td><td>${badge(p.status)}</td><td>${badge(p.mapping_state)}</td></tr>`),shown.map(p=>recordCard({title:p.location||'No Location ID',open:'printer:'+p.id,status:badge(p.status),identity:p.serial,meta:[['Location',(p.building||'Unknown')+' / Floor '+(p.floor||'Unknown')],['HN / EPR',p.epr?'HN'+p.epr:'Unknown'],['Mapping',p.mapping_state],...(S.issues.some(i=>i.printer_id===p.id&&i.state==='Open')?[['Latest note','Open issue · '+(S.issues.find(i=>i.printer_id===p.id&&i.state==='Open').next_action||'Review notes')]]:[])],controls:labelMode?check(p):`<button type="button" class="primary" data-printer-quick="${esc(p.id)}" ${canEdit()?'':'disabled'}>Update relabeling</button>`})))+`<div class="pagination"><button data-act="prev" ${page?'':'disabled'}>Previous</button><span>${page+1} / ${Math.max(1,Math.ceil(list.length/40))}</span><button data-act="next" ${(page+1)*40<list.length?'':'disabled'}>Next</button></div>`:empty('No matching printers','Try a serial, another floor or clear filters.'))
}

function routeWork(){return head('Relabel route')+renderRouteSession(routeSession,{canEdit:canEdit()})}
function printerQuick(id){if(!guard(()=>printerQuick(id)))return;opened={kind:'printer',id};detailAction='quick';const p=S.printers.find(p=>p.id===id);if(!p){notice('Printer unavailable');return}const issue=S.issues.find(i=>i.printer_id===id&&i.state==='Open');modal('Update relabeling',`<p class="identifier">${esc(p.location||'No Location ID')} · ${esc(p.serial)}</p><p>${badge(p.status)} · ${esc(p.building||'Unknown')} / Floor ${esc(p.floor||'Unknown')}</p>${issue?'<p class="warning">An open issue exists. Changing its status requires a resolution outcome.</p>':''}<div class="quick-work-actions"><button type="button" data-printer-action="printed" ${canEdit()?'':'disabled'}>Record physically Printed</button><button type="button" class="primary" data-printer-action="complete" ${canEdit()?'':'disabled'}>Complete physical verification</button><button type="button" data-printer-action="issue" ${canEdit()?'':'disabled'}>Report issue / add note</button><button type="button" data-work-open="printer:${esc(id)}">View printer details</button></div>`,'',false)}
function issues(){let list=S.issues.filter(i=>i.state===issueState),rows=[],cards=[];for(let i of list){let p=S.printers.find(p=>p.id===i.printer_id);let latest=i.notes.at(-1)?.text||i.imported_details||'';rows.push(`<tr><td><button class="row-link" data-open="issue:${i.id}">${esc(p?.location||p?.serial||'Unknown printer')}</button><br><small class="muted">${esc(p?.serial)}</small></td><td>${esc(i.type||'—')}</td><td>${esc(i.owner||'Unassigned')}</td><td>${esc(i.next_action||latest)}</td><td>${dateDisplay(i.reported_at||i.reported_date)}</td><td>${badge(i.state)}</td></tr>`);cards.push(recordCard({title:p?.location||p?.serial||'Unknown printer',open:'issue:'+i.id,status:badge(i.state),identity:p?.serial,meta:[['Owner',i.owner||'Unassigned'],['Type',i.type||'Unspecified'],['Latest note',latest]],action:i.next_action}))}return head('Issues')+`<div class="toolbar view-tabs"><button data-act="open-issues" class="${issueState==='Open'?'primary':''}">Open · ${S.issues.filter(i=>i.state==='Open').length}</button><button data-act="resolved-issues" class="${issueState==='Resolved'?'primary':''}">Resolved · ${S.issues.filter(i=>i.state==='Resolved').length}</button></div>`+(list.length?table(['Printer','Type','Owner','Next action / Notes','Reported','State'],rows,cards):empty(`No ${issueState.toLowerCase()} issues`))}
function tasks(){let agenda=S.agenda.filter(a=>a.work_date===selectedDate),list=agenda.map(a=>{let t=S.tasks.find(t=>t.id===a.task_id);return t&&selectedDate<S.today&&a.snapshot?{...t,...JSON.parse(a.snapshot),id:t.id}:t}).filter(Boolean).filter(t=>(todayOwner==='all'||t.owner===S.identity.actor||t.owner===S.identity.actor.split(' · ')[0])&&(!todayBlocked||t.status==='Blocked')).sort((a,b)=>['High','Moderate','Low'].indexOf(a.priority)-['High','Moderate','Low'].indexOf(b.priority)),archive=S.archives.filter(a=>a.work_date===selectedDate);return head(selectedDate===S.today?'Today':'Agenda',`<button class="primary" data-open="task:new" ${canEdit()?'':'disabled'}>New task</button>`)+`<div class="work-launcher"><button class="primary" data-view="tickets">Add ticket to agenda</button><button data-view="printers">Relabel printers</button><button data-view="units">Prepare / deploy</button></div><div class="toolbar"><input type="date" id="agenda-date" aria-label="Work date" value="${selectedDate}"><button data-act="today-date">Today</button><button data-act="all-agendas">Past agendas</button></div><div class="toolbar view-tabs"><button data-act="today-all" class="${todayOwner==='all'?'primary':''}">All owners</button><button data-act="today-mine" class="${todayOwner==='mine'?'primary':''}">Mine</button><button data-act="today-blocked" aria-pressed="${todayBlocked}">${todayBlocked?'Blocked only':'Blocked'}</button></div><div class="countline"><span>${list.length} tasks · ${list.filter(t=>t.status==='Done').length} done</span><span>${esc(selectedDate)}${selectedDate<S.today?' · Saved agenda snapshot':''}</span></div>`+(list.length?taskTable(list):empty('No scheduled work','Add a task or schedule ticket and provisioning work for this date.'))+(archive.length?`<h2 class="section-title">Imported agenda snapshots</h2><div class="warning">The original archive has no Task IDs. These rows remain separate historical records.</div>${taskTable(archive,true)}`:'')+todayShortcuts()}
function todayShortcuts(){const due=S.blockers.filter(b=>!b.closed_at&&b.follow_up&&b.follow_up<=S.today);return `<section class="panel"><h2>Follow-ups</h2>${due.length?`<p>${due.length} active blocker follow-ups due or overdue; separate from this agenda.</p><button data-view="blocked">Review blocked work</button>`:'<p class="muted">No blocker follow-ups due.</p>'}</section>${routeStore.list().length?`<section class="panel"><h2>Saved route filters</h2><div class="linklist">${routeStore.list().map(route=>`<button data-load-route="${esc(route.name)}">${esc(route.name)} →</button>`).join('')}</div></section>`:''}`}
function taskTable(list,archived=false){return table(['Priority','Task','Location','Owner','Status','Action',...(archived?[]:['Linked work'])],list.map(t=>`<tr><td>${badge(t.priority)}</td><td>${archived?esc(t.title):`<button class="row-link" data-open="task:${t.id}">${esc(t.title)}</button>`}</td><td>${esc(t.location)}</td><td>${esc(t.owner)}</td><td>${badge(t.status)}</td><td>${esc(t.action)}</td>${archived?'':`<td>${agendaLinks(t,S)}</td>`}</tr>`),list.map(t=>recordCard({title:t.title,open:archived?'':'task:'+t.id,status:badge(t.status),meta:[['Priority',t.priority],['Location',t.location],['Owner',t.owner||'Unassigned']],action:t.action,controls:archived?'':agendaLinks(t,S)+`<button type="button" data-task-quick="${esc(t.id)}" ${canEdit()?'':'disabled'}>Update work status</button>`})))}
function blockers(){let list=S.blockers.filter(b=>blockedHistory?b.closed_at:!b.closed_at).sort((a,b)=>String(a.follow_up||'9999').localeCompare(String(b.follow_up||'9999')));return head('Blocked work')+`<div class="toolbar view-tabs"><button data-act="blocked-current" class="${!blockedHistory?'primary':''}">Active</button><button data-act="blocked-history" class="${blockedHistory?'primary':''}">History</button></div>`+(list.length?table(['Task','Reason / Waiting on','Follow-up','Owner','Status'],list.map(b=>{let t=S.tasks.find(t=>t.id===b.task_id);return `<tr><td><button class="row-link" data-open="task:${t?.id}">${esc(t?.title)}</button></td><td>${esc(b.reason||'Reason needed')}<br><small>${esc(b.waiting_on||'Waiting on needed')}</small></td><td>${esc(b.follow_up||'—')}</td><td>${esc(t?.owner)}</td><td>${badge(b.closed_at?'Unblocked':b.display)}</td></tr>`}),list.map(b=>{let t=S.tasks.find(t=>t.id===b.task_id);return recordCard({title:t?.title||'Unknown task',open:t?'task:'+t.id:'',status:badge(b.closed_at?'Unblocked':b.display),meta:[['Reason',b.reason||'Reason needed'],['Waiting on',b.waiting_on||'Details needed'],['Follow-up',b.follow_up||'No follow-up'],['Owner',t?.owner||'Unassigned'],...(b.closed_at?[['Outcome',b.outcome],['Closed',dateDisplay(b.closed_at)]]:[])]})})):empty('No '+(blockedHistory?'blocker history':'blocked work')))}
function units(){let q=uf.q.trim().toUpperCase(),list=S.units.filter(u=>(!q||[u.legacy_id,u.printer,u.serial,u.location,u.ticket].some(v=>String(v||'').toUpperCase().includes(q)))&&(!uf.owner||u.owner===uf.owner||uf.owner==='__blank'&&!u.owner)&&(!uf.status||u.derived_status===uf.status));let controls=listToolbar(`<input class="search" id="unit-search" aria-label="Find provisioning unit" placeholder="PR ID, printer, serial, location or ticket" value="${esc(uf.q)}">`,`<label>Owner<select data-unit-filter="owner">${opts([...new Set(S.units.map(u=>u.owner).filter(Boolean))].sort(),uf.owner,'All owners')}<option value="__blank" ${uf.owner==='__blank'?'selected':''}>Unassigned</option></select></label><label>Status<select data-unit-filter="status">${opts([...new Set(S.units.map(u=>u.derived_status).filter(Boolean))].sort(),uf.status,'All statuses')}</select></label>`,'<button class="tertiary" data-act="clear-unit-filters">Clear</button>');return head('Provisioning',`<button class="primary" data-open="unit:new" ${canEdit()?'':'disabled'}>New request</button>`)+controls+`<div class="countline"><span>${list.length} / ${S.units.length} units</span><span>${S.units.filter(u=>u.derived_status==='Complete').length} complete · ${S.units.filter(u=>u.derived_status==='Blocked').length} blocked</span></div>`+(list.length?table(['ID / Printer','Location','Owner','Stage','Status','Next action'],list.map(u=>`<tr><td><button class="row-link" data-open="unit:${u.id}">${esc(u.legacy_id)}</button><br>${esc(u.printer||'Unassigned')}</td><td>${esc(u.location)}</td><td>${esc(u.owner)}</td><td>${esc(u.stage)}</td><td>${badge(u.derived_status)}</td><td>${esc(u.next_action)}</td></tr>`),list.map(u=>recordCard({title:u.legacy_id,open:'unit:'+u.id,status:badge(u.derived_status),identity:u.printer||'Unassigned printer',meta:[['Location',u.location],['Owner',u.owner||'Unassigned'],['Stage',u.stage]],action:u.next_action}))):empty(S.units.length?'No matching units':'No provisioning requests',S.units.length?'Clear filters or try another identifier.':'Create a request before assigning a name or serial.'))}
let tf={q:'',building:'',priority:'',state:'',owner:''};
function ticketAgendaButton(t){const tasks=agendaCandidates('ticket',t,S),count=tasks.filter(task=>S.agenda.some(a=>a.task_id===task.id&&a.work_date===selectedDate)).length;return `${count?`<span class="muted">${count} linked work item${count===1?'':'s'} on ${esc(selectedDate)}</span>`:''}<button type="button" class="primary" data-work-schedule="ticket:${esc(t.id)}" ${canEdit()?'':'disabled'}>${count?'Manage agenda':'Add to agenda'}</button>`}
function source(t,k){return ticketSource(t,k)}
function tickets(){let list=S.tickets.filter(t=>(!tf.q||[t.number,source(t,'short_description'),t.location,t.printer].some(v=>String(v).toLowerCase().includes(tf.q.toLowerCase())))&&(!tf.building||t.building===tf.building)&&(!tf.priority||source(t,'priority')===tf.priority)&&(!tf.state||source(t,'state')===tf.state)&&(!tf.owner||source(t,'assigned_to')===tf.owner));return head('Tickets',`<button data-act="import-tickets" ${isPreview?'disabled title="Server imports are unavailable in the browser preview"':''} ${S.identity.role==='import-admin'?'':'disabled'}>Import CSV</button>`)+`<p class="agenda-context">Planning for ${esc(selectedDate)} · ${isPreview?'This browser only':'Local agenda'}<button data-view="today">View agenda</button></p>${listToolbar(`<input class="search" id="ticket-search" aria-label="Find ticket" placeholder="Ticket, description or printer" value="${esc(tf.q)}">`,`${[['building','Building',t=>t.building],['priority','Priority',t=>source(t,'priority')],['state','State',t=>source(t,'state')],['owner','Owner',t=>source(t,'assigned_to')]].map(([k,label,fn])=>`<label>${esc(label)}<select data-ticket-filter="${k}" aria-label="${label}">${opts([...new Set(S.tickets.map(fn).filter(Boolean))],tf[k],label)}</select></label>`).join('')}`)}<div class="countline"><span>${list.length} tickets</span><span>ServiceNow fields retain source authority</span></div>`+(list.length?table(['Priority','Ticket','Short description','Location','Owner','State','Agenda'],list.map(t=>`<tr><td>${esc(source(t,'priority'))}</td><td><button class="row-link" data-open="ticket:${t.id}">${esc(t.number)}</button>${t.missing_from_latest?'<br><small class="flag">Absent from latest export</small>':''}</td><td>${esc(source(t,'short_description'))}</td><td>${esc(t.location||source(t,'location'))}</td><td>${esc(source(t,'assigned_to'))}</td><td>${esc(source(t,'state'))}</td><td>${ticketAgendaButton(t)}</td></tr>`),list.map(t=>recordCard({title:t.number,open:'ticket:'+t.id,status:badge(source(t,'state')),identity:source(t,'short_description'),meta:[['Priority',source(t,'priority')],['Location',t.location||source(t,'location')],['Owner',source(t,'assigned_to')],['Source',t.missing_from_latest?'Absent from latest export; closure unknown':'Present in latest export']],action:t.action,controls:ticketAgendaButton(t)}))):empty('No matching tickets'))}
let mq='';
function mappings(){let list=S.mappings.filter(m=>m.active!==false&&(!mq||[m.location,m.epr,m.lws_id,m.review].some(v=>String(v||'').toUpperCase().includes(mq.toUpperCase().replace(/^HN/,'')))));return head('LWS mappings',`<button data-act="import-mappings" ${isPreview?'disabled title="Server imports are unavailable in the browser preview"':''} ${S.identity.role==='import-admin'?'':'disabled'}>Import snapshot</button>`)+`${listToolbar(`<input class="search" id="mapping-search" aria-label="Find mapping" value="${esc(mq)}" placeholder="Location, EPR, LWS ID or review">`)}<div class="warning">Upstream item 25 → EPR. Item .1 → LWS record ID. Mapping rows identify locations, not unique physical printers.</div><div class="countline"><span>${list.length} active mappings</span><span>${list.filter(m=>m.review).length} review messages</span></div>`+table(['Location ID','EPR','LWS ID','Review'],list.slice(0,150).map(m=>`<tr><td>${esc(m.location)}</td><td>${esc(m.epr)}</td><td>${esc(m.lws_id)}</td><td>${esc(m.review||'—')}</td></tr>`),[mappingCandidates(list.slice(0,150),{dateDisplay})])+(list.length>150?'<p class="muted">Showing 150 matches; narrow your search.</p>':'')}
function tools(){return head('Tools')+`<div class="split"><section class="panel"><h2>Identifier label</h2><label>Location ID<input id="label-location" maxlength="20" placeholder="CT3876BL2"></label><label>EPR<input id="label-epr" inputmode="numeric" maxlength="4" placeholder="8872"></label><div class="step-actions"><button data-act="lookup-label">Look up mapping</button><button class="primary" data-act="generate-label">Generate ZPL</button></div><div id="label-output"></div><p class="muted">ZD421 · 203 dpi · RAW ZPL export. Printer sender is unconfigured. Exported and Sent do not mean physically Printed or Complete.</p></section><section class="panel"><h2>Data</h2><div class="linklist">${isPreview?'':'<a href="/api/export" download>Download read-only records CSV</a>'}<button data-act="download-full">${isPreview?'Download preview snapshot':'Download complete read-only snapshot'}</button><button data-act="download-reconciliation">Download reconciliation report</button><button data-act="print-receipts" ${isPreview||!canEdit()?'disabled':''}>${isPreview?'Send receipt import unavailable in preview':'Import Windows send receipts'}</button><button data-act="import-records" ${isPreview?'disabled':''} ${S.identity.role==='import-admin'?'':'disabled'}>Import versioned record updates</button></div><hr class="divider"><h2>Reference tools</h2><div class="linklist">${isPreview?'':'<button data-act="copy-exporter">Copy ServiceNow exporter</button>'}<button data-act="zsu">Review ZSU configuration</button>${Object.entries(S.settings.links?.data||{}).filter(([k,v])=>v).map(([k,v])=>`<a href="${esc(v)}" target="_blank" rel="noopener">${esc(k)}</a>`).join('')||'<span class="muted">Internal reference links are unconfigured. Add approved links in Settings.</span>'}</div></section></div><h2 class="section-title">Label batch history</h2>`+(S.jobs.length?table(['Batch','Location','HN / EPR','Result','Time'],S.jobs.map(j=>`<tr><td>${esc(j.batch_id?.slice(0,8))}</td><td>${esc(j.location)}</td><td>HN${esc(j.epr)}</td><td>${badge(j.result)}</td><td>${dateDisplay(j.at)}</td></tr>`),S.jobs.map(j=>recordCard({title:j.location,status:badge(j.result),meta:[['HN / EPR','HN'+j.epr],['Time',dateDisplay(j.at)],['Detail',j.detail]]}))):empty('No label batches'))}
function history(){return head('History')+`<h2 class="section-title">Past agendas</h2><div class="toolbar">${[...new Set([...S.agenda.map(a=>a.work_date),...S.archives.map(a=>a.work_date)])].sort().reverse().map(d=>`<button data-date="${d}">${d}</button>`).join('')||'<span class="muted">No saved agendas</span>'}</div><h2 class="section-title">Audit</h2>`+(S.audit.length?table(['Action','Actor','Time','Record'],S.audit.map(a=>`<tr><td><button class="row-link" data-audit="${a.id}">${esc(a.action)}</button></td><td>${esc(a.actor)}</td><td>${dateDisplay(a.at)}</td><td>${esc(a.entity_id)}</td></tr>`),S.audit.map(a=>recordCard({title:a.action,meta:[['Actor',a.actor],['Time',dateDisplay(a.at)]],controls:`<button class="tertiary" data-audit="${a.id}">View event</button>`}))):empty('No new audit events','Imported source dates retain their original precision.'))}
function settings(){return head('Settings')+`<div class="split"><section class="panel"><h2>Area rules</h2><p class="muted">Lowest order wins. Comma-separated VBA Like patterns; a leading minus excludes. Rule status does not affect matching.</p>${S.rules.map(r=>`<div class="settings-row"><div class="row"><strong>${r.order} · ${esc(r.area)}</strong><button data-open="rule:${r.id}">Edit</button></div><p class="identifier">${esc(r.match)}</p>${badge(r.status)}</div>`).join('')}<button data-open="rule:new" ${S.identity.role==='import-admin'?'':'disabled'}>Add rule</button></section><section class="panel"><h2>Team, aliases and links</h2>${['team','aliases','links'].map(k=>`<button data-settings="${k}">Edit ${k}</button>`).join(' ')}<p>${S.team.map(t=>`${esc(t.name)} · ${esc(t.username)}`).join('<br>')}</p><hr class="divider"><h2>Integrations</h2><p>Authentication: labeled development identities. Organizational SSO is unconfigured.</p><p>ServiceNow: CSV ingestion; no writeback.</p><p>PPME / Epic / LWS: imported snapshots; no writeback.</p><p>Printer sender: unconfigured; ZPL export is available.</p><div class="warning">Whitelist copy says WPA3 Enterprise. The source ZSU template uses PEAP/WPA with certificate validation disabled. IT must verify the approved configuration.</div></section></div>`}
function more(){return head('More')+secondaryMore(S.identity)}

function field(k,label,value='',type='text',full=false){return `<label class="${full?'full':''}">${esc(label)}<input name="${k}" type="${type}" value="${esc(value)}" ${k==='epr'?'maxlength="4" inputmode="numeric"':''} ${k==='owner'?'list="team-names"':''} ${['serial','location','printer','epr'].includes(k)?'autocorrect="off" autocapitalize="off" spellcheck="false"':''}></label>`}
