function datums(data){return `<div class="data-grid">${Object.entries(data).map(([k,v])=>`<div class="datum"><small>${esc(k)}</small>${esc(v===undefined||v===null||v===''?'Unknown':v)}</div>`).join('')}</div>`}
function modal(title,content,footer='',form=true){
 if(!guard(()=>modal(title,content,footer,form)))return;
 if(!dialog.open){modalURL=window.location?.href||'';const active=document.activeElement;listContext={x:window.scrollX||0,y:window.scrollY||0,focus:['data-open','id','data-act','data-view','data-settings','data-audit','data-work-open','data-work-schedule','data-printer-quick','data-task-quick'].map(key=>[key,active?.getAttribute?.(key)])};pushModalHistory()}
 pending=null;uncertain=false;versionOverride=null;initialForm='';
 const teamOptions=(S.settings.team?.data||S.team).map(t=>`<option value="${esc(t.name)}">${esc(t.username)}</option>`).join('');
 body.innerHTML=detailLayout(title,content,footer,teamOptions,form);dialog.classList.toggle('short-sheet',Boolean(detailAction)||['Filters','Routes'].includes(title));
 if(!dialog.open)dialog.showModal();wireDialog();initialForm=draftSignature();
 const formElement=$('#edit-form');if(formElement){const edited=()=>{if(!saving){clearFieldErrors();receipt=null;$('.save-state').textContent=dirty()?'Unsaved changes':''}};formElement.addEventListener('input',edited);formElement.addEventListener('change',edited)}
}
function mappingDetail(p){const rows=S.mappings.filter(m=>m.active!==false&&m.location===p.location);return `<details class="printer-mappings" ${p.mapping_state==='Ready'?'':'open'}><summary>Mapping · ${esc(p.mapping_state)}</summary>${rows.length?rows.map(m=>`<div class="mapping-candidate">${datums({'HN / EPR':m.epr?'HN'+m.epr:'Unknown','LWS ID':m.lws_id,'Review':m.review||'No review message','Source batch / import':m.source_batch||m.source_import||m.batch_id,'Source row':m.source_row,'Mapping record ID':m.id})}</div>`).join(''):'<p>No confirmed mapping.</p>'}<p class="muted">Candidates identify a location, not a unique physical printer. Label export still checks ambiguity.</p></details>`}

function receiptHTML(){return receipt&&receiptKey===opened?.kind+':'+opened?.id?`<p class="save-receipt" role="status">${esc(receipt)}${refreshFailed?' Current records could not refresh.':''}</p>${refreshFailed?'<button type="button" data-act="refresh-detail">Refresh records</button>':''}`:''}
function taskDetail(t){detailAction='';modal(t.title||'Work item',receiptHTML()+taskRead(t,S,{canEdit:canEdit(),dateDisplay,badge}),'',false);showReceiptState()}
function taskAction(action){if(!guard(()=>taskAction(action)))return;const task=S.tasks.find(t=>t.id===opened.id);receipt=null;if(action==='edit'){open('task',task.id,{edit:true});detailAction='edit';return}detailAction='status';const b=S.blockers.find(b=>b.task_id===task.id&&!b.closed_at);modal('Update work status',`<h3>${esc(task.title)}</h3>${select('status','Work status',task.status,['Planned','In progress','Blocked','Done','Canceled'])}<section id="task-block-fields">${area('reason','Reason',b?.reason||'')}${field('waiting_on','Waiting on',b?.waiting_on||'')}${field('follow_up','Follow-up',b?.follow_up||'','date')}${area('blocker_notes','Blocker notes',b?.notes||'')}</section>${b?area('unblock_outcome','Unblocking outcome'):''}<p class="muted">Updates this work item only. Ticket source state and physical printer status stay separate.</p>`,`<button type="submit" class="primary" ${canEdit()?'':'disabled'}>Save work status</button>`);const blockFields=$('#task-block-fields'),status=$('[name=status]');const show=()=>{blockFields.hidden=status.value!=='Blocked'};status.addEventListener('change',show);show();let current=task;$('#edit-form').onsubmit=async e=>{e.preventDefault();await submit('task',taskPayload(current,S,formData()),{onReapply:latest=>{current=latest}})}}
function scheduleWork(kind,id){if(!guard(()=>scheduleWork(kind,id)))return;const collection={ticket:'tickets',unit:'units',issue:'issues',task:'tasks'}[kind],record=S[collection]?.find(r=>r.id===id);if(!record){notice('Work record unavailable');return}opened={kind,id};receipt=null;detailAction='agenda';const seed=agendaSeed(kind,record);modal('Add to agenda',`<h3>${esc(kind==='ticket'?record.number:kind==='unit'?record.printer||record.legacy_id:record.title||'Printer issue')}</h3>${agendaForm(kind,record,S,{date:selectedDate,canEdit:canEdit()})}<section id="new-agenda-work"><div class="form-grid">${field('title','Work to do',seed.title||'','text',true)}${field('owner','Owner',seed.owner||S.identity.actor)}${select('priority','Local priority',seed.priority||'Moderate',['High','Moderate','Low'])}${area('action','Next action',seed.action||'',true)}</div></section>`,`<button type="submit" class="primary" ${canEdit()?'':'disabled'}>Add to agenda</button>`);const choose=$('[name=agenda_task_id]'),section=$('#new-agenda-work');const change=()=>{section.hidden=choose.value!=='__new__';for(const input of section.querySelectorAll('input,select,textarea'))input.disabled=section.hidden;$('[name=title]').required=!section.hidden};choose.addEventListener('change',change);change();initialForm=draftSignature();let latestVersion=null;
 $('#edit-form').onsubmit=async e=>{e.preventDefault();const data=formData(),date=data.work_date;if(data.agenda_task_id==='__new__'){await submit('task',{...seed,title:data.title,owner:data.owner,priority:data.priority,action:data.action,work_date:date},{agendaDate:date})}else{const task=S.tasks.find(t=>t.id===data.agenda_task_id);if(!task){$('#save-error').textContent='Choose existing work or create a work item';return}await submit('schedule',{id:task.id,version:latestVersion?.id===task.id?latestVersion.version:task.version,work_date:date},{agendaDate:date,onReapply:latest=>{latestVersion=latest}})}}
}
function unitRead(u){detailAction='';modal(u.legacy_id||'Provisioning',receiptHTML()+(refreshFailed?'<div class="warning">Saved fields are shown. Derived status and the full refreshed checklist are not confirmed current until Refresh succeeds.</div>':'')+unitReadView(u,S,{canEdit:canEdit(),dateDisplay,badge}),'',false);showReceiptState()}
function ticketDetail(t){detailAction='';modal(t.number,receiptHTML()+`<section class="ticket-work-summary"><h3>${esc(source(t,'short_description')||'Ticket work')}</h3><p>${esc(t.location||source(t,'location')||'Location not recorded')} · ${esc(source(t,'state')||'Source state unknown')}</p>${t.action?`<p>Next action: ${esc(t.action)}</p>`:''}<p>Agenda date: ${esc(selectedDate)}</p>${ticketAgendaButton(t)}<div class="step-actions">${agendaCandidates('ticket',t,S).map(task=>`<button type="button" data-work-open="task:${esc(task.id)}">${esc(task.title)} · ${esc(task.status)}</button>`).join('')}</div></section>`+ticketRead(t,{role:S.identity.role,dateDisplay}),'',false);showReceiptState()}
function ticketAction(){if(!guard(ticketAction))return;const t=S.tickets.find(t=>t.id===opened.id);receipt=null;detailAction='annotations';modal('Edit annotations',ticketAnnotations(t,{role:S.identity.role}),`<button type="submit" class="primary" ${canEdit()?'':'disabled'}>Save annotations</button>`);bindSave('ticket',t)}
function unitAction(section){if(!guard(()=>unitAction(section)))return;const u=S.units.find(u=>u.id===opened.id);receipt=null;detailAction=section;modal({request:'Edit request',technical:'Technical fields',stage:'Stage and deployment',tests:'Tests',next:'Update next action'}[section],unitFocusedForm(u,section),`<button type="submit" class="primary" ${canEdit()?'':'disabled'}>Save fields</button>`);$('#edit-form').onsubmit=async e=>{e.preventDefault();await submit('unit',mergeUnitFields(u,formData()))}}
function unitStep(key){
 if(!guard(()=>unitStep(key)))return;let u=S.units.find(u=>u.id===opened.id),fieldsAcknowledged=false;receipt=null;detailAction='step';
 modal('Confirm provisioning step',stepForm(u,S,key),`<button type="submit" class="primary" ${canEdit()?'':'disabled'}>Save step</button>`);
 const saveStep=async draft=>submit('steps',stepPayload(u,S,key,draft),{partialFields:fieldsAcknowledged,onReapply:latest=>{u=latest}});
 $('#edit-form').onsubmit=async e=>{e.preventDefault();const draft=formData();if((u.steps||[]).some(step=>step.key!==key&&!step.checked_date)){const error=$('#save-error');error.textContent='Not saved. An existing step has an unknown date; the current server endpoint would replace it. Preserve the draft for a separate backend correction.';error.focus();return}const changed=unitEditableFields.some(k=>Object.hasOwn(draft,k)&&draft[k]!== (u[k]??''));
  if(changed){await submit('unit',mergeUnitFields(u,draft),{keepForm:true,onReapply:latest=>{u=latest},onAcknowledged:async()=>{u=S.units.find(x=>x.id===u.id);fieldsAcknowledged=true;await saveStep(draft)}})}else await saveStep(draft);
 };
}
function printerRead(p){
 const hist=S.issues.filter(i=>i.printer_id===p.id),activeIssue=hist.find(i=>i.state==='Open');detailAction='';
 modal(p.location||'No Location ID',`${receiptHTML()}<div class="record-summary"><p class="identifier">Serial ${esc(p.serial)}</p>${badge(p.status)}</div>${datums({'Building / Floor':`${p.building||'Unknown'} / ${p.floor||'Unknown'}`,'HN / EPR':p.epr?'HN'+p.epr:'Unknown','Last status update':p.status_changed_at?dateDisplay(p.status_changed_at):'Unknown historical date','By':p.status_changed_by||p.legacy_by})}${mappingDetail(p)}${activeIssue?`<section class="open-issue"><h3>Open issue</h3><p>${esc(activeIssue.next_action||activeIssue.notes?.at(-1)?.text||'No next action recorded')}</p><button type="button" data-open-issue="${esc(activeIssue.id)}">View issue and notes</button></section>`:''}<div class="record-actions"><button type="button" data-printer-action="issue" ${canEdit()?'':'disabled'}>Report issue</button><button type="button" data-printer-action="printed" ${canEdit()?'':'disabled'}>Record Printed</button><button type="button" data-printer-action="status" ${canEdit()?'':'disabled'}>Other status changes</button></div><details><summary>Status and issue history · ${hist.length}</summary>${hist.map(i=>`<h3>${badge(i.state)} · ${dateDisplay(i.reported_at||i.reported_date)}</h3>${noteTimeline(i)}${i.imported_details?`<p>Source details: ${esc(i.imported_details)}</p>`:''}${i.outcome?`<p>Outcome: ${esc(i.outcome)}</p>`:''}<button type="button" data-open-issue="${i.id}">Open issue</button>`).join('')||'<p>No issues</p>'}${(p.observations||[]).map(o=>`<p>${esc(o.text)} · ${esc(o.actor||'Unknown')} · ${dateDisplay(o.at)}</p>`).join('')}${datums({'Physical verification':p.physical_verified_at?dateDisplay(p.physical_verified_at):'Unknown','Verified by':p.physical_verified_by})}</details>`,`<button type="button" class="primary" data-printer-action="complete" ${canEdit()?'':'disabled'}>Complete verification</button>`,false);
 showReceiptState();
}
function issueRead(i){
 const p=S.printers.find(p=>p.id===i.printer_id);detailAction='';
 modal(p?.location||'Issue',`${receiptHTML()}<p class="identifier">Serial ${esc(p?.serial)}</p>${badge(i.state)}${datums({'Owner':i.owner,'Type':i.type,'Next action':i.next_action,'Reporter':i.reporter,'Reported':dateDisplay(i.reported_at||i.reported_date)})}<h3>Notes</h3>${noteTimeline(i)}${i.imported_details?`<details><summary>Source details and provenance</summary><p>${esc(i.imported_details)}</p>${(i.source_provenance||[]).map(v=>`<p>${esc(JSON.stringify(v))}</p>`).join('')}</details>`:''}${i.state==='Resolved'?datums({'Outcome':i.outcome,'Resolved':dateDisplay(i.resolved_at||i.resolved_date)}):`<div class="record-actions"><button type="button" data-issue-action="edit" ${canEdit()?'':'disabled'}>Edit issue</button><button type="button" data-issue-action="resolve" ${canEdit()?'':'disabled'}>Resolve and set status</button></div>`}`,i.state==='Open'?`<button type="button" class="primary" data-issue-action="note" ${canEdit()?'':'disabled'}>Add note</button>`:'',false);showReceiptState();
}
function showReceiptState(){if(receipt&&receiptKey===opened?.kind+':'+opened?.id&&$('.save-state'))$('.save-state').textContent=receipt}
function printerAction(mode){
 if(!guard(()=>printerAction(mode)))return;
 const p=S.printers.find(p=>p.id===opened.id),issue=S.issues.find(i=>i.printer_id===p.id&&i.state==='Open');detailAction=mode;receipt=null;
 const status=mode==='complete'?'Complete':mode==='issue'?'Issue':mode==='printed'?'Printed':'Pending';
 const title={complete:'Complete verification',printed:'Record physically Printed',issue:'Report issue',status:issue?'Resolve and set status':'Change status'}[mode];
 modal(title,`<p class="identifier">${esc(p.location||'No Location ID')} · ${esc(p.serial)}</p>${mode==='status'?select('status','Resulting status',status,['Pending','Printed']):`<input type="hidden" name="status" value="${status}">`}${mode==='printed'?'<p>Record Printed only after physically printing the label. ZPL export or a send receipt does not establish this.</p>':''}${mode==='issue'?area('note','Issue note'):''}${issue&&mode!=='issue'?`<div class="warning">An open issue exists. This save resolves it and sets the selected printer status.</div>${area('outcome','Resolution outcome')}`:''}${mode==='complete'?'<label class="check"><input name="physical_verified" type="checkbox" required>I physically verified this printer’s location, applied label and print/scan before marking Complete.</label>':''}${mode!=='issue'?area('observation','Physical observation (optional)'):''}`,`<button type="submit" class="primary" ${canEdit()?'':'disabled'}>${mode==='complete'?'Save Complete':mode==='issue'?'Save issue':mode==='printed'?'Save Printed':'Save status'}</button>`);bindSave('printer',p);
}
function issueAction(mode){
 if(!guard(()=>issueAction(mode)))return;
 const i=S.issues.find(i=>i.id===opened.id);receipt=null;
 if(mode==='resolve'){open('printer',i.printer_id);printerAction('status');return}
 detailAction=mode;
 const content=mode==='note'?area('text','Add note'):select('type','Type',i.type||'',['','Not found','Moved','Location mismatch','EPR/routing mismatch','Label problem','Other'])+field('owner','Owner',i.owner)+area('next_action','Next action',i.next_action)+`<details><summary>Link a blocker</summary><label class="check"><input type="checkbox" name="block" ${isPreview?'disabled':''}>Create blocked work for this issue${isPreview?' (server app only)':''}</label>${field('reason','Reason')}${field('waiting_on','Waiting on')}${field('follow_up','Follow-up','','date')}</details>`;
 modal(mode==='note'?'Add note':'Edit issue',content,`<button type="submit" class="primary" ${canEdit()?'':'disabled'}>${mode==='note'?'Save note':'Save issue'}</button>`);bindSave(mode==='note'?'note':'issue',i);
}
function open(kind,id,seed={}){if($('.intro-overlay[open]')){deferredRecord={kind,id,seed};if(!deferredTimer)deferredTimer=setTimeout(()=>{deferredTimer=null;const record=deferredRecord;deferredRecord=null;if(record)open(record.kind,record.id,record.seed)},100);return}if(!guard(()=>open(kind,id,seed)))return;opened={kind,id};detailAction='';let d={printer:S.printers,issue:S.issues,task:S.tasks,unit:S.units,ticket:S.tickets,rule:S.rules}[kind]?.find(x=>x.id===id)||seed;
 if(kind==='printer'){if(!d.id){notice('Printer unavailable');return}printerRead(d)
 }else if(kind==='issue'){if(!d.id){notice('Issue unavailable');return}issueRead(d)
 }else if(kind==='task'){
  if(d.id&&!seed.edit){taskDetail(d);return}
  let b=S.blockers.find(b=>b.task_id===d.id&&!b.closed_at);let dates=S.agenda.filter(a=>a.task_id===d.id).map(a=>a.work_date);modal(d.id?'Task':'New task',`<div class="form-grid">${field('title','Task',d.title||'','text',true)}${field('owner','Owner',d.owner||'')}${select('priority','Priority',d.priority||'Moderate',['High','Moderate','Low'])}${select('status','Status',d.status||'Planned',['Planned','In progress','Blocked','Done','Canceled'])}${field('work_date','Work date',selectedDate,'date')}${field('location','Location',d.location||'','text',true)}${area('action','Action',d.action||'',true)}${field('ticket','Ticket',d.ticket||'')}${select('unit_id','Provisioning unit',d.unit_id||'',['',...S.units.map(u=>u.id)])}${field('issue_id','Issue ID',d.issue_id||'')}</div><details ${b?'open':''}><summary>Block / Unblock</summary>${area('reason','Reason',b?.reason||'')}${field('waiting_on','Waiting on',b?.waiting_on||'')}${field('follow_up','Follow-up',b?.follow_up||'','date')}${area('blocker_notes','Blocker notes',b?.notes||'')}${b?area('unblock_outcome','Unblocking outcome'):''}<p class="muted">Choose Blocked to capture a blocker. Choose a new status and enter an outcome to unblock. Work date schedules this same task.</p></details>${dates.length?`<p class="muted">Scheduled: ${dates.join(', ')}</p>`:''}${S.blockers.filter(x=>x.task_id===d.id&&x.closed_at).map(b=>`<details><summary>Unblocked ${dateDisplay(b.closed_at)}</summary><p>${esc(b.reason)} · ${esc(b.waiting_on)}</p><p>${esc(b.outcome)} → ${esc(b.closed_as)}</p></details>`).join('')}`,`<button type="submit" class="primary" ${canEdit()?'':'disabled'}>Save</button>`);bindSave('task',d)
 }else if(kind==='unit'){
  if(d.id){unitRead(d);return}
  modal(d.legacy_id||'New provisioning request',`<div class="form-grid">${field('printer','Printer name',d.printer||'')}${field('quantity','Quantity',1,'number')}${area('location','Location',d.location||'',true)}${field('building','Building',d.building||'')}${field('owner','Owner',d.owner||'')}${select('stage','Stage',d.stage||'Requested',['Requested','Preparing','Ready','Deployed','Canceled'])}${field('ticket','Ticket',d.ticket||'')}${area('next_action','Next action',d.next_action||'',true)}${select('blocked_by','Blocked by',d.blocked_by||'',['','Stock/hardware','Clinic info','Other team','Access','Leadership decision'])}${field('deployed','Deployed',d.deployed||'','date')}${select('result','Site test',d.result||'Not tested',['Not tested','Pass','Fail'])}${field('tested','Site test date',d.tested||'','date')}${select('bench_result','Bench test',d.bench_result||'Not tested',['Not tested','Pass','Fail'])}${field('bench_tested','Bench test date',d.bench_tested||'','date')}${area('notes','Notes',d.notes||'',true)}</div><details><summary>Technical fields</summary><div class="form-grid">${[['epr','EPR'],['lws_id','LWS ID'],['model','Model'],['serial','Serial'],['mac','Wi-Fi MAC'],['ip','IP']].map(([k,t])=>field(k,t,d[k]||'')).join('')}</div></details>${d.id?`<div class="step-actions"><button type="button" data-steps="${d.id}">Nine steps</button><button type="button" data-schedule-unit="${d.id}">Add to selected day</button><button type="button" data-unit-label="${d.id}">Label handoff</button></div><p>Derived status: ${badge(d.derived_status)}</p>`:''}`,`<button type="submit" class="primary" ${canEdit()?'':'disabled'}>Save</button>`);bindSave('unit',d)
 }else if(kind==='ticket'){ticketDetail(d)
 }else if(kind==='rule'){
  modal(d.id?'Area rule':'New area rule',`${field('order','Order',d.order||1,'number')}${field('area','Area',d.area||'')}${select('status','Status',d.status||'Pending',['Pending','In progress','Complete'])}${area('match','Match',d.match||'')}<p class="muted">Example: CT5*, -CT5800* · * any text, ? one character, # one digit, [0-9] character range.</p>`,`<button type="submit" class="primary" ${S.identity.role==='import-admin'?'':'disabled'}>Save</button>`);bindSave('rule',d)
 }}
function noteTimeline(i){return `<ul class="timeline">${i.notes.map(n=>`<li><small>${esc(n.actor||'Unknown author')} · ${n.at?dateDisplay(n.at):'Imported; exact note time unknown'}${n.provenance?' · '+esc(n.provenance):''}</small>${esc(n.text)}</li>`).join('')}</ul>`}
function formData(){let f=$('#edit-form'),d=Object.fromEntries(new FormData(f));for(let i of f.querySelectorAll('input[type=checkbox]'))d[i.name]=i.checked;for(let k of ['quantity','order'])if(k in d)d[k]=Number(d[k]);return d}
