function conflictHTML(latest,draft){
 const labels={status:'Printer status',owner:'Owner',type:'Issue type',next_action:'Next action',note:'New note',text:'New note',outcome:'Resolution outcome',observation:'Physical observation',physical_verified:'Physical assertion'};
 const display=(key,value)=>key==='checked'?(value||[]).map(k=>S.steps.find(([id])=>id===k)?.[1]||k).join('; ')||'No steps recorded':key==='dates'?Object.entries(value||{}).map(([k,date])=>(S.steps.find(([id])=>id===k)?.[1]||k)+': '+(date||'Unknown date')).join('; '):typeof value==='object'?JSON.stringify(value):value;
 const latestValue=k=>k==='checked'?latest.steps?.map(s=>s.key):k==='dates'?Object.fromEntries((latest.steps||[]).map(s=>[s.key,s.checked_date])):latest[k];
 const fields=Object.keys(draft).filter(k=>!['id','version'].includes(k));
 return `<section class="conflict-review"><h3>Record changed since you opened it</h3><p>Your draft is preserved. Compare it with the latest record before explicitly reapplying.</p>${latest.status_changed_by?`<p>Latest status: ${esc(latest.status_changed_by)} · ${dateDisplay(latest.status_changed_at)}</p>`:''}<dl>${fields.map(k=>`<div><dt>${esc(labels[k]||k.replaceAll('_',' '))}</dt><dd><span>Latest saved:</span> ${esc(k==='note'||k==='text'?latest.notes?.at(-1)?.text||'No note':display(k,latestValue(k))??'Not recorded')}</dd><dd><span>Your draft:</span> ${esc(draft[k]===true?'Checked':draft[k]===false?'Unchecked':display(k,draft[k])||'Blank')}</dd></div>`).join('')}</dl><button type="button" id="reapply">Keep draft and reapply to latest version</button></section>`
}
function clearFieldErrors(){for(const input of body.querySelectorAll('[aria-invalid]')){input.removeAttribute('aria-invalid');input.removeAttribute('aria-describedby')}for(const message of body.querySelectorAll('.inline-field-error'))message.remove()}
function markErrorField(error){const names=[...body.querySelectorAll('[name]')].map(input=>input.name),key=errorField(error.textContent,names);if(!key)return;const input=[...body.querySelectorAll('[name]')].find(input=>input.name===key);input.setAttribute('aria-invalid','true');input.setAttribute('aria-describedby','save-error');const label=input.closest('label'),inline=document.createElement('span');inline.className='inline-field-error';inline.textContent=error.textContent;if(label)label.append(inline);const link=document.createElement('button');link.type='button';link.className='error-field-link';link.textContent='Review '+key.replaceAll('_',' ');const focus=()=>{input.focus();input.scrollIntoView({block:'nearest'})};link.onclick=focus;error.append(link);focus()}

function applyResult(action,result){
 const record=action==='printer'?result.record:result;
 const collection={printer:'printers',issue:'issues',note:'issues',unit:'units',steps:'units',task:'tasks',schedule:'tasks',ticket:'tickets',rule:'rules'}[action];
 if(collection&&Array.isArray(record)){for(const item of record){const at=S[collection].findIndex(r=>r.id===item.id);if(at>=0)S[collection][at]={...S[collection][at],...item};else S[collection].push(item)}}
 if(collection&&record?.id){const at=S[collection].findIndex(r=>r.id===record.id);if(at>=0)S[collection][at]={...S[collection][at],...record};else S[collection].push(record)}
 if(action==='printer'&&result.issue){const at=S.issues.findIndex(i=>i.id===result.issue.id);if(at>=0)S.issues[at]=result.issue;else S.issues.push(result.issue)}
}
async function submit(action,b,options={}){
 if(saving)return null;
 if(versionOverride?.action===action&&versionOverride.id===b.id)b={...b,version:versionOverride.version};
 const serialized=JSON.stringify({action,body:b});
 if(uncertain&&pending?.serialized!==serialized){$('#save-error').textContent='Save not confirmed. Retry the original unchanged draft first, or verify the record before discarding it.';return null}
 if(!pending||pending.serialized!==serialized)pending={serialized,request_id:crypto.randomUUID()};
 const attemptDraft=draftSignature();const state=$('.save-state'),error=$('#save-error');saving=true;state.textContent='Saving…';error.textContent='';clearFieldErrors();
 const buttons=[...body.querySelectorAll('button,input,select,textarea')];const disabled=buttons.map(x=>x.disabled);buttons.forEach(x=>x.disabled=true);
 let result,acknowledged=false;
 try{result=await api('mutate',{request_id:pending.request_id,action,body:b});acknowledged=true}
 catch(e){
  uncertain=!e.status||e.status>=500;state.textContent=uncertain?'Save not confirmed':'Not saved';error.textContent=e.message;error.focus();if(uncertain){$('#conflict').innerHTML='<p>The server acknowledgment was unavailable. Retry uses the same request ID.</p><button type="button" id="retry-unconfirmed">Retry original save safely</button>';$('#retry-unconfirmed').onclick=()=>{if(draftSignature()!==attemptDraft){error.textContent='The draft changed after the uncertain save. Restore the original values before retrying, or verify the record before discarding.';return}submit(action,b,options)}}
  if(e.latest){uncertain=false;let latest=e.latest,canReapply=true;
   if(['steps','unit','task','schedule'].includes(action)){try{const current=await api('state');latest=current[action==='task'||action==='schedule'?'tasks':'units'].find(r=>r.id===b.id)||latest;if(action==='task'){const blocker=current.blockers.find(x=>x.task_id===b.id&&!x.closed_at);latest={...latest,reason:blocker?.reason||'',waiting_on:blocker?.waiting_on||'',follow_up:blocker?.follow_up||'',blocker_notes:blocker?.notes||''}}S=current;render()}catch{if(action==='steps'||action==='task'){canReapply=false;error.textContent+=' Latest checklist or blocker details could not refresh. Keep the draft and try Save again to retrieve them.'}}}
   $('#conflict').innerHTML=conflictHTML(latest,b);$('#reapply').disabled=!canReapply;$('#reapply').onclick=()=>{versionOverride={action,id:b.id,version:latest.version};options.onReapply?.(latest);pending=null;$('#reapply').disabled=true;error.textContent='Draft preserved. Press Save only after reviewing the latest saved values.'}
  }
  if(options.partialFields){error.textContent=(uncertain?'Unit fields saved; step save not confirmed. ':'Unit fields saved; steps not saved. ')+error.textContent;state.textContent=uncertain?'Unit fields saved · Step save not confirmed':'Unit fields saved · Steps not saved'}
  markErrorField(error);return null;
 }finally{if(!acknowledged){saving=false;buttons.forEach((x,i)=>x.disabled=disabled[i]);const invalid=body.querySelector('[aria-invalid=true]');if(invalid&&!invalid.disabled){invalid.focus();invalid.scrollIntoView({block:'nearest'})}}}
 // The write is acknowledged. From here onward failures are reads/presentation, never an unsaved mutation.
 pending=null;uncertain=false;state.textContent='Saved · Refreshing records…';applyResult(action,result);if(action==='steps'){const u=S.units.find(u=>u.id===b.id);const old=new Map((u.steps||[]).map(step=>[step.key,step]));u.steps=b.checked.map(key=>({...(old.get(key)||{}),key,checked_date:b.dates[key]||old.get(key)?.checked_date||'',actor:old.get(key)?.checked_date===b.dates[key]?old.get(key)?.actor:S.identity.actor}));}
 try{await load()}catch(e){refreshFailed=true;render()}
 saving=false;buttons.forEach((x,i)=>x.disabled=disabled[i]);versionOverride=null;
 if(options.keepForm){state.textContent='Unit fields saved; step not saved';if(options.onAcknowledged)await options.onAcknowledged(result);return result}
 initialForm=draftSignature();
 if(['printer','issue','note'].includes(action)){
  const record=action==='printer'?result.record:result;
  const label=action==='printer'?(b.status==='Issue'?'Issue recorded':b.status==='Complete'?'Complete verification saved':'Status saved · '+b.status):action==='note'?'Note added':'Issue updated';
  const timestamp=action==='printer'?record?.status_changed_at:action==='note'?record?.notes?.at(-1)?.at:record?.updated_at;
  receiptKey=(action==='printer'?'printer':'issue')+':'+b.id;receipt=label+' · '+(isPreview?'Saved in this browser': 'Saved'+(timestamp?' · '+dateDisplay(timestamp):''));detailAction='';
  if(action==='printer')printerRead(S.printers.find(p=>p.id===b.id));else issueRead(S.issues.find(i=>i.id===b.id));render();
 }else if(action==='task'||action==='schedule'){opened={kind:'task',id:result.id};receiptKey='task:'+result.id;receipt=(options.agendaDate?'Added to agenda · '+options.agendaDate:action==='schedule'?'Added to agenda':'Work saved')+' · '+(isPreview?'Saved in this browser':'Saved');detailAction='';taskDetail(S.tasks.find(t=>t.id===result.id)||result);if(options.agendaDate){const button=document.createElement('button');button.type='button';button.className='primary';button.textContent='View agenda';button.onclick=()=>{closeDetail();selectedDate=options.agendaDate;todayOwner='all';todayBlocked=false;view='today';render()};$('.dialog-foot').append(button)}render()}else if(action==='unit'||action==='steps'){const record=Array.isArray(result)?result[0]:result;opened={kind:'unit',id:record.id};receiptKey='unit:'+record.id;receipt=(action==='steps'?'Step changes saved':'Unit fields saved')+' · '+(isPreview?'Saved in this browser':'Saved');unitRead(S.units.find(u=>u.id===record.id));render()}else if(action==='ticket'){opened={kind:'ticket',id:b.id};receiptKey='ticket:'+b.id;receipt='Annotations saved · '+(isPreview?'Saved in this browser':'Saved');ticketDetail(S.tickets.find(t=>t.id===b.id));render()}else{detailAction='';const label={task:'Task saved',rule:'Area rule saved',settings:'Settings saved',label_batch:'ZPL handoff exported; not sent or physically printed',label_receipts:'Send receipts recorded; physical status unchanged',import_commit:'Import committed'}[action]||'Changes saved';receiptKey='';receipt=null;modal(label,`<p role="status">${esc(label)} · ${isPreview?'Saved in this browser':'Saved'}${refreshFailed?'. Current records could not refresh.':''}</p>${action==='task'?datums({'Task':result.title,'Owner':result.owner,'Status':result.status,'Action':result.action}):''}`,action==='task'?`<button type="button" data-edit-task="${esc(result.id)}">Edit task</button>`:'',false)}
 return result;
}
