function download(name,content,type='application/json'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([content],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function steps(id){let u=S.units.find(x=>x.id===id);opened={kind:'unit',id};modal(`${u.legacy_id} · Provisioning steps`,`<div class="warning">Step completion is a field assertion. A ZPL export does not establish printed, applied or deployed.</div>${S.steps.map(([key,label])=>{let s=u.steps.find(s=>s.key===key);return `<div class="step"><input type="checkbox" id="check-${key}" aria-label="${esc(label)}" name="step-${key}" ${s?'checked':''}><label for="check-${key}">${esc(label)}<small>${s?esc(s.actor||'Imported actor unknown'):'Unchecked'}</small></label><input type="date" aria-label="${key} date" name="date-${key}" value="${s?.checked_date||S.today}"></div>`}).join('')}<label class="check separated"><input name="sync_action" type="checkbox">Use first unchecked step as Next action</label><div class="step-actions"><button type="button" data-whitelist="${id}">Copy whitelist request</button><button type="button" data-lws-request="${id}">Copy LWS request</button><button type="button" data-act="zsu">Review ZSU config</button></div>`,`<button type="submit" class="primary" ${canEdit()?'':'disabled'}>Save steps</button>`);$('#edit-form').onsubmit=async e=>{e.preventDefault();let d=formData(),checked=S.steps.filter(([k])=>d['step-'+k]).map(([k])=>k);await submit('steps',{id,version:u.version,checked,dates:Object.fromEntries(checked.map(k=>[k,d['date-'+k]])),sync_action:d.sync_action})}}
async function reviewLabels(){let visible=new Set(filteredPrinters().map(p=>p.id)),items=[...selected].map(id=>({id,hidden:!visible.has(id)}));let reviews=await api('label-review',{items});opened=null;modal('Review labels',`<p>${reviews.length} labels · ${reviews.filter(r=>r.hidden).length} outside current filters</p>${reviews.map(r=>`<article class="card"><div class="row"><strong>${esc(r.location||r.serial)}</strong>${badge(r.state)}</div><div class="sub">${esc(r.serial)} · HN${esc(r.epr)} ${r.hidden?'· Hidden selection':''}</div>${r.reason?`<div class="error-box">${esc(r.reason)}</div>`:''}${r.warnings.map(w=>`<div class="warning">${esc(w)}</div>`).join('')}</article>`).join('')}<label class="check"><input name="acknowledge_warnings" type="checkbox">I reviewed shared mappings, source warnings and hidden selections.</label><p class="muted">Export revalidates all mappings. It does not send, clear selections, or set Printed / Complete.</p>`,`<button type="submit" class="primary" ${reviews.some(r=>r.state==='Error')||!canEdit()?'disabled':''}>Export reviewed ZPL</button>`);$('#edit-form').onsubmit=async e=>{e.preventDefault();let r=await submit('label_batch',{items:reviews.map(r=>({id:r.id,version:r.version,hidden:r.hidden})),acknowledge_warnings:formData().acknowledge_warnings});if(r){download('beaker-labels-'+r.batch_id+'.zpl',r.zpl,'text/plain');download('beaker-manifest-'+r.batch_id+'.json',JSON.stringify(r.manifest,null,2))}}}
async function importCSV(kind){opened=null;modal('Import '+kind,`<div class="warning">Preview validates before any operational records change. Rejected rows block the entire commit.</div><label>CSV file<input type="file" id="import-file" accept=".csv,text/csv"></label>${kind==='mappings'?'<p>Required headings: Location ID, item 25, item .1, Review. Item numbers are mandatory; do not relabel upstream fields based on their wording.</p>':kind==='records'?'<p>Required: id, kind, version, data (JSON). Only task, unit, ticket and rule updates; lifecycle mutations use their dedicated forms.</p>':'<p>Use the original ServiceNow export, including export_timestamp_utc or its original timestamped filename.</p>'}<div id="import-result"></div>`,'<button type="submit" class="primary">Preview</button>');$('#edit-form').onsubmit=async e=>{e.preventDefault();let file=$('#import-file').files[0];if(!file){$('#save-error').textContent='Choose a CSV file';return}try{$('.save-state').textContent='Validating…';let p=await api('import-preview',{kind,filename:file.name,raw:await file.text()});$('.save-state').textContent='Preview ready';$('#import-result').innerHTML=`<h3>${p.count} accepted · ${p.rejected_count} rejected</h3>${p.errors.map(e=>`<div class="error-box">${esc(e)}</div>`).join('')}<pre>${esc(JSON.stringify(p.accepted.slice(0,5),null,2))}</pre>${p.rejects.length?`<pre>${esc(JSON.stringify(p.rejects,null,2))}</pre><button type="button" id="download-rejects">Download rejected rows</button>`:''}${p.can_commit?'<button type="button" class="primary" id="commit-import">Commit import</button>':''}`;if($('#download-rejects'))$('#download-rejects').onclick=()=>download('beaker-rejected-rows.json',JSON.stringify(p.rejects,null,2));if($('#commit-import'))$('#commit-import').onclick=async()=>{await submit('import_commit',{id:p.id})}}catch(e){$('.save-state').textContent='Not imported';$('#save-error').textContent=e.message}}}
async function zsu(){let text=await fetch('/zsu-template.txt').then(r=>r.text());modal('ZSU configuration · IT verification required',`<div class="warning">Source whitelist says WPA3 Enterprise. This source template uses PEAP/WPA and disables server-certificate validation. IT must verify compatibility and approval before sending.</div><pre>${esc(text)}</pre><label class="check"><input type="checkbox" id="it-verified">IT verified this exact configuration</label><label>Wi-Fi password (not saved)<input type="password" id="wifi-password" autocomplete="off"></label>`,'<button type="button" id="copy-zsu">Copy configuration</button>');$('#copy-zsu').onclick=async()=>{if(!$('#it-verified').checked){$('#save-error').textContent='IT verification is required';return}let pass=$('#wifi-password').value;if(!pass||/["\r\n]/.test(pass)){$('#save-error').textContent='Enter a password without quotes or line breaks';return}try{await navigator.clipboard.writeText(text.replace('{{PASSWORD}}',pass));$('#wifi-password').value='';initialForm=draftSignature();closeDetail();notice('Configuration copied; password was not saved')}catch{$('#save-error').textContent='Clipboard unavailable. Password has not been saved; keep editing or close.'}}}
function exitRoute(){routeSession?.exit();routeSession=null;routeQuery=null}
function wireWork(root){for(const button of (root?.querySelectorAll?.('[data-work-open]')||[]))button.onclick=()=>open(...button.dataset.workOpen.split(':'));for(const button of (root?.querySelectorAll?.('[data-work-schedule]')||[]))button.onclick=()=>scheduleWork(...button.dataset.workSchedule.split(':'));for(const button of (root?.querySelectorAll?.('[data-work-find]')||[]))button.onclick=()=>{if(!guard(()=>button.click()))return;closeDetail();exitRoute();filters={q:button.dataset.workFind,building:'',floor:'',status:'',area:''};page=0;view='printers';render()};for(const button of (root?.querySelectorAll?.('[data-printer-quick]')||[]))button.onclick=()=>printerQuick(button.dataset.printerQuick);for(const button of (root?.querySelectorAll?.('[data-task-quick]')||[]))button.onclick=()=>{open('task',button.dataset.taskQuick);taskAction('status')}}
function wire(){wireWork($('#app'));for(const b of document.querySelectorAll('[data-load-route]'))b.onclick=()=>{const route=routeStore.list().find(r=>r.name===b.dataset.loadRoute);if(route){exitRoute();filters={...route.filters};sortKey=route.sort;activeRoute=route.name;page=0;view='printers';render()}};for(const b of document.querySelectorAll('[data-clear-filter]'))b.onclick=()=>{exitRoute();filters[b.dataset.clearFilter]='';page=0;activeRoute='';render()};if($('#saved-route'))$('#saved-route').onchange=e=>{let route=routeStore.list().find(r=>r.name===e.target.value);activeRoute=route?.name||'';if(route){exitRoute();filters={...route.filters};sortKey=route.sort;page=0}render()};if($('#unit-search'))$('#unit-search').oninput=e=>{let pos=e.target.selectionStart;uf.q=e.target.value;render();$('#unit-search').focus();$('#unit-search').setSelectionRange(pos,pos)};for(let f of document.querySelectorAll('[data-unit-filter]'))f.onchange=()=>{uf[f.dataset.unitFilter]=f.value;render()};for(let b of document.querySelectorAll('[data-view]'))b.onclick=()=>{view=b.dataset.view;render()};for(let b of document.querySelectorAll('[data-open]'))b.onclick=()=>open(...b.dataset.open.split(':'));for(let b of document.querySelectorAll('[data-act]'))b.onclick=()=>act(b.dataset.act);for(let i of document.querySelectorAll('[data-select]'))i.onchange=()=>{i.checked?selected.add(i.dataset.select):selected.delete(i.dataset.select);render()};for(let f of document.querySelectorAll('[data-filter]'))f.onchange=()=>{exitRoute();filters[f.dataset.filter]=f.value;activeRoute='';page=0;render()};if($('#search'))$('#search').oninput=e=>{let pos=e.target.selectionStart;exitRoute();filters.q=e.target.value;activeRoute='';page=0;render();$('#search').focus();$('#search').setSelectionRange(pos,pos)};if($('#sort'))$('#sort').onchange=e=>{exitRoute();sortKey=e.target.value;activeRoute='';render()};if($('#agenda-date'))$('#agenda-date').onchange=e=>{selectedDate=e.target.value||S.today;render()};if($('#ticket-search'))$('#ticket-search').oninput=e=>{tf.q=e.target.value;let p=e.target.selectionStart;render();$('#ticket-search').focus();$('#ticket-search').setSelectionRange(p,p)};for(let f of document.querySelectorAll('[data-ticket-filter]'))f.onchange=()=>{tf[f.dataset.ticketFilter]=f.value;render()};if($('#mapping-search'))$('#mapping-search').oninput=e=>{mq=e.target.value;let p=e.target.selectionStart;render();$('#mapping-search').focus();$('#mapping-search').setSelectionRange(p,p)};for(let b of document.querySelectorAll('[data-date]'))b.onclick=()=>{selectedDate=b.dataset.date;view='today';render()};for(let b of document.querySelectorAll('[data-audit]'))b.onclick=()=>{let a=S.audit.find(a=>a.id===b.dataset.audit);modal(a.action,datums({'Actor':a.actor,'Server time':dateDisplay(a.at),'Request ID':a.request_id})+`<h3>Before</h3><pre>${esc(a.before_json)}</pre><h3>After</h3><pre>${esc(a.after_json)}</pre>`,'',false)};for(let b of document.querySelectorAll('[data-settings]'))b.onclick=()=>editSettings(b.dataset.settings)}
function wireDialog(){wireWork(body);for(const button of body.querySelectorAll('[data-task-action]'))button.onclick=()=>taskAction(button.dataset.taskAction);for(const b of body.querySelectorAll('[data-edit-task]'))b.onclick=()=>open('task',b.dataset.editTask);for(const b of body.querySelectorAll('[data-unit-action]'))b.onclick=()=>unitAction(b.dataset.unitAction);for(const b of body.querySelectorAll('[data-unit-step]'))b.onclick=()=>unitStep(b.dataset.unitStep);for(const b of body.querySelectorAll('[data-ticket-action]'))b.onclick=()=>ticketAction();for(const b of body.querySelectorAll('[data-printer-action]'))b.onclick=()=>printerAction(b.dataset.printerAction);for(const b of body.querySelectorAll('[data-issue-action]'))b.onclick=()=>issueAction(b.dataset.issueAction);for(const b of body.querySelectorAll('[data-open-issue]'))b.onclick=()=>open('issue',b.dataset.openIssue);for(let b of body.querySelectorAll('[data-act]'))b.onclick=()=>act(b.dataset.act);for(let b of body.querySelectorAll('[data-resolve-printer]'))b.onclick=()=>{open('printer',b.dataset.resolvePrinter);let s=$('[name=status]');s.value='Pending';$('[name=outcome]').focus()};for(let b of body.querySelectorAll('[data-steps]'))b.onclick=async()=>{let u=S.units.find(x=>x.id===b.dataset.steps);let result=await submit('unit',{...formData(),id:u.id,version:u.version});if(result)steps(u.id)};for(let b of body.querySelectorAll('[data-schedule-unit]'))b.onclick=()=>scheduleWork('unit',b.dataset.scheduleUnit);for(let b of body.querySelectorAll('[data-schedule-ticket]'))b.onclick=()=>scheduleWork('ticket',b.dataset.scheduleTicket);for(let b of body.querySelectorAll('[data-unit-label]'))b.onclick=async()=>{let u=S.units.find(x=>x.id===b.dataset.unitLabel);if($('#edit-form')){let result=await submit('unit',{...formData(),id:u.id,version:u.version});if(!result)return}u=S.units.find(x=>x.id===u.id);dialog.close();view='tools';render();$('#label-location').value=u.printer;$('#label-epr').value=u.epr};for(let b of body.querySelectorAll('[data-whitelist]'))b.onclick=()=>{let u=S.units.find(x=>x.id===b.dataset.whitelist);if(!u.mac||!u.model){$('#save-error').textContent='Enter and save Wi-Fi MAC and model first';return}copy(`Radio frequencies: 3.4GHz, 5, 6\nWi-Fi protected access: WPA3 Enterprise\nMAC address: ${u.mac}\nDescription: ${u.model}\nReason: Beaker project`)};for(let b of body.querySelectorAll('[data-lws-request]'))b.onclick=()=>{let u=S.units.find(x=>x.id===b.dataset.lwsRequest);if(!/^[A-Z0-9]{1,20}$/.test(u.printer)||!u.serial||!u.model){$('#save-error').textContent='Enter and save PPME Location ID, serial and model first';return}copy(`Printer name: ${u.printer}\nHostname: ${u.serial}.medforest.org\nLocation: ${u.location.replaceAll('\n',', ')}\nModel: ${u.model}`)}}
async function editSettings(key){if(!guard(()=>editSettings(key)))return;opened=null;detailAction='';let setting=S.settings[key]||{data:key==='team'?S.team.map(t=>({name:t.name,username:t.username})):key==='aliases'?{CT:'Clarkson Tower',UT:'University Tower'}:{},version:0};modal('Edit '+key,area('json','Values (JSON)',JSON.stringify(setting.data,null,2)),`<button type="submit" class="primary" ${S.identity.role==='import-admin'?'':'disabled'}>Save</button>`);$('#edit-form').onsubmit=async e=>{e.preventDefault();try{await submit('settings',{key,data:JSON.parse(formData().json),version:setting.version})}catch(e){$('#save-error').textContent=e.message}}}
async function act(a){try{
 if(a==='route-start'){if(!guard(()=>act(a)))return;routeQuery={filters:{...filters},sort:sortKey};routeSession=createRouteSession({name:activeRoute||'Current filters',printers:routeMatches(),allPrinters:S.printers});closeDetail();view='printers';render();return}
 if(a==='route-previous'||a==='route-next'){routeSession?.[a==='route-next'?'next':'previous']();render();return}
 if(a==='route-refresh'){await load();return}
 if(a==='route-exit'){exitRoute();render();return}
 if(a==='today-all'||a==='today-mine'){todayOwner=a==='today-mine'?'mine':'all';render();return}
 if(a==='today-blocked'){todayBlocked=!todayBlocked;render();return}
 if(['save-route','routes','filters','checklist','zsu','print-receipts'].includes(a)||a.startsWith('import-')){if(!guard(()=>act(a)))return;opened=null;detailAction='';}
 if(a==='detail-back'){backDetail();return}
 if(a==='refresh-detail'){try{await load();open(opened.kind,opened.id)}catch(e){refreshFailed=true;notice('Saved. Current records could not refresh.')}return}
 if(a==='toggle-labels'){labelMode=!labelMode;render();return}
 if(a==='filters'){
  modal('Filters',filterFields().replaceAll('data-filter=','data-sheet-filter='),'<button type="submit" class="primary">Apply filters</button>');
  $('#edit-form').onsubmit=e=>{e.preventDefault();exitRoute();for(const f of body.querySelectorAll('[data-sheet-filter]'))filters[f.dataset.sheetFilter]=f.value;activeRoute='';page=0;initialForm=draftSignature();closeDetail();render()};return
 }
 if(a==='routes'){modal('Routes',routeControls()+'<button type="button" class="primary" data-act="route-start">Start session route</button>'+ '<button type="button" data-act="checklist">Route checklist</button>','',false);wire();return}
 if(a==='clear-unit-filters'){uf={q:'',owner:'',status:''};render();return}if(a==='remove-route'){routeStore.remove(activeRoute);activeRoute='';render();notice('Saved route removed from this browser');return}if(a==='save-route'){modal('Save route',`<label>Name<input name="route_name" maxlength="60" required value="${esc(activeRoute)}" autocomplete="off"></label><p class="muted">Stores current search, filters and sort in this browser. Printer records and label selections are not included.</p>`,'<button type="submit" class="primary">Save route</button>');$('#edit-form').onsubmit=e=>{e.preventDefault();try{activeRoute=routeStore.save(formData().route_name,filters,sortKey).name;initialForm=draftSignature();closeDetail();render();notice('Route saved in this browser')}catch(error){$('#save-error').textContent=error.message}};return}if(a==='close'){closeDetail();return}if(a==='refresh')await load();if(a==='clear'){exitRoute();filters={q:'',building:'',floor:'',status:'',area:''};activeRoute='';page=0;render()}if(a==='prev'){page--;render()}if(a==='next'){page++;render()}if(a==='select-visible'){filteredPrinters().forEach(p=>selected.add(p.id));render()}if(a==='clear-selection'){selected.clear();render()}if(a==='review')await reviewLabels();if(a==='checklist'){let list=filteredPrinters();modal('Route checklist',`<p>${list.length} printers · as of ${dateDisplay(S.as_of)}</p><p>Use the browser Print command after closing this panel. Current filtered route is printed with identifiers and status; check physical completion in the app.</p>`,'<button type="button" id="print-route">Print route</button>',false);$('#print-route').onclick=()=>{dialog.close();let saved=page;page=0;let html=table(['Location ID','Serial','HN / EPR','Floor','Status','Verified'],list.map(p=>`<tr><td>${esc(p.location)}</td><td>${esc(p.serial)}</td><td>HN${esc(p.epr)}</td><td>${esc(p.floor)}</td><td>${esc(p.status)}</td><td>□</td></tr>`),[]);let original=$('.workspace').innerHTML;$('.workspace').innerHTML=`<h1>Beaker · Route checklist</h1><p>${dateDisplay(S.as_of)} · ${list.length} printers</p>${html}`;window.print();$('.workspace').innerHTML=original;page=saved;wire()}}if(a==='open-issues'){issueState='Open';render()}if(a==='resolved-issues'){issueState='Resolved';render()}if(a==='today-date'){selectedDate=S.today;render()}if(a==='all-agendas'){view='history';render()}if(a==='blocked-current'){blockedHistory=false;render()}if(a==='blocked-history'){blockedHistory=true;render()}if(a==='print-receipts'){modal('Import send receipts','<label>Receipt JSON<input id="receipt-file" type="file" accept=".json,application/json"></label><div class="warning">Receipts are adapter assertions, retained with provenance. They never set Printed or Complete. Unknown results require investigation before any new job.</div>','<button type="submit" class="primary">Record results</button>');$('#edit-form').onsubmit=async e=>{e.preventDefault();try{let file=$('#receipt-file').files[0];if(!file)throw new Error('Choose a receipt file');let payload=JSON.parse(await file.text());let r=await submit('label_receipts',payload);if(r){r.clear_selection.forEach(id=>selected.delete(id));render()}}catch(e){$('#save-error').textContent=e.message}}}if(a.startsWith('import-'))await importCSV(a.slice(7));if(a==='logout'){await api('logout',{});exitRoute();selected.clear();receipt=null;S=null;await start()}if(a==='lookup-label'){let loc=$('#label-location').value.trim().toUpperCase(),m=S.mappings.filter(m=>m.active!==false&&m.location===loc);let e=[...new Set(m.map(m=>m.epr))];if(e.length!==1)throw new Error(e.length?'Ambiguous mapping; review all rows in Mappings':'No mapping found');$('#label-epr').value=e[0];notice('Mapping found; verify the physical printer')}if(a==='generate-label'){let r=await api('zpl',{location:$('#label-location').value,epr:$('#label-epr').value});$('#label-output').innerHTML=`<pre>${esc(r.zpl)}</pre><button id="download-label">Download .zpl</button><button id="standalone-handoff" ${canEdit()?'':'disabled'}>Export recorded handoff</button>`;$('#download-label').onclick=()=>download('beaker-label.zpl',r.zpl,'text/plain');$('#standalone-handoff').onclick=async()=>{try{let output=await api('mutate',{request_id:crypto.randomUUID(),action:'standalone_label',body:{location:$('#label-location').value,epr:$('#label-epr').value}});download('beaker-standalone-'+output.batch_id+'.json',JSON.stringify(output.manifest,null,2));download('beaker-standalone-'+output.batch_id+'.zpl',output.zpl,'text/plain');await load();notice('Handoff exported; not sent')}catch(e){notice(e.message)}};notice('ZPL generated; not sent')}if(a==='download-full')download('beaker-readonly-snapshot.json',JSON.stringify(S,null,2));if(a==='download-reconciliation')download('beaker-reconciliation.json',JSON.stringify(await api('reconciliation'),null,2));if(a==='copy-exporter')await copy(await fetch('/servicenow-exporter.js.txt').then(r=>r.text()));if(a==='zsu')await zsu()}catch(e){notice(e.message)}}
async function start(){let session=await api('session');if(session.actor){await load();return}$('#app').innerHTML=`<main class="signin"><div class="brand"><span class="brand-mark"></span>Beaker</div><h1>${isPreview?'Open Beaker preview':'Open development workspace'}</h1><p>${isPreview?'Synthetic demo only. Changes stay in this browser; they are not shared team records. Choose a preview role to explore.':'Choose a labeled development identity. These roles enforce permissions on the server. Organizational sign-in is unconfigured.'}</p>${Object.entries(session.users||{}).map(([user,[name,role]])=>`<button data-login="${user}">${esc(name)}<small>${esc(role)}</small></button>`).join('')}<div id="login-error" class="error-box" role="alert"></div></main>`;for(let b of document.querySelectorAll('[data-login]'))b.onclick=async()=>{try{await api('login',{user:b.dataset.login});await load()}catch(e){$('#login-error').textContent=e.message}}}
window.addEventListener('focus',()=>{if(S&&!dialog.open)load().catch(e=>notice(e.message))});dialog.addEventListener?.('cancel',e=>{e.preventDefault();backDetail()});dialog.addEventListener?.('close',()=>{if(!dialog.open){releaseModalHistory();restoreContext()}});start().catch(e=>{$('#app').innerHTML=`<main class="signin"><h1>Beaker unavailable</h1><p>${esc(e.message)}</p><button id="retry-start">Retry</button></main>`;$('#retry-start').onclick=start});
